import { reserve, release } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/ours-g4-2/bot.mjs';
import { mkdtempSync, utimesSync, mkdirSync } from 'node:fs';
import { execFile } from 'node:child_process';
import { tmpdir } from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';

const STATE = mkdtempSync(path.join(tmpdir(), 'state-'));
process.env.STATE_DIR = STATE;
const MIN = 60_000, H = 60 * MIN;
const T0 = new Date('2026-10-22T10:00:00Z');
const at = (ms) => new Date(T0.getTime() + ms);
const req = (o = {}) => ({ userId: 'lead_204', maxPerWindow: 3, windowHours: 24, minGapMinutes: 90, ...o });
const spawnReserve = (r, ms) => new Promise((res, rej) => {
  const code = `import('${'<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/ours-g4-2/bot.mjs'}').then(m=>m.reserve(${JSON.stringify(r)}, new Date(${at(ms).getTime()}))).then(x=>console.log(JSON.stringify(x)))`;
  execFile(process.execPath, ['--input-type=module', '-e', code], { env: process.env }, (e, out, err) => e ? rej(err || e) : res(JSON.parse(out)));
});

// 1. Concurrency: 12 processes race on one lead, gap 0, max 3 -> exactly 3 win
{
  const rs = await Promise.all(Array.from({ length: 12 }, () => spawnReserve(req({ minGapMinutes: 0 }), 0)));
  const ok = rs.filter((r) => r.allowed);
  assert.equal(ok.length, 3, JSON.stringify(rs));
  assert.ok(rs.filter((r) => !r.allowed).every((r) => r.reason === 'max_per_window_reached'));
  console.log('ok 1 concurrency: 3 of 12 allowed across processes');
}

// 2. Gap: 90 min minimum
{
  const L = 'gap_lead';
  const a = await reserve(req({ userId: L, minGapMinutes: 90 }), at(0));
  assert.equal(a.allowed, true);
  const b = await reserve(req({ userId: L, minGapMinutes: 90 }), at(30 * MIN));
  assert.deepEqual(b, { allowed: false, reason: 'min_gap_not_elapsed', reservationId: null });
  const c = await reserve(req({ userId: L, minGapMinutes: 90 }), at(90 * MIN));
  assert.equal(c.allowed, true);
  console.log('ok 2 min gap');
}

// 3. Rolling window: max 2 per 1h; slot frees when the oldest ages out
{
  const L = 'win_lead';
  const r = (ms) => reserve(req({ userId: L, maxPerWindow: 2, windowHours: 1, minGapMinutes: 0 }), at(ms));
  assert.equal((await r(0)).allowed, true);
  assert.equal((await r(10 * MIN)).allowed, true);
  assert.equal((await r(20 * MIN)).reason, 'max_per_window_reached');
  assert.equal((await r(59 * MIN)).reason, 'max_per_window_reached');
  assert.equal((await r(61 * MIN)).allowed, true); // t=0 aged out
  console.log('ok 3 rolling window');
}

// 4. Release frees the slot; release from another process; double release no-op
{
  const L = 'rel_lead';
  const r1 = req({ userId: L, maxPerWindow: 1, windowHours: 24, minGapMinutes: 0 });
  const a = await reserve(r1, at(0));
  assert.equal(a.allowed, true);
  assert.equal((await reserve(r1, at(1))).reason, 'max_per_window_reached');
  await new Promise((res, rej) => execFile(process.execPath, ['--input-type=module', '-e',
    `import('<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/ours-g4-2/bot.mjs').then(m=>m.release('${a.reservationId}'))`],
    { env: process.env }, (e) => e ? rej(e) : res()));
  const b = await reserve(r1, at(2));
  assert.equal(b.allowed, true);
  await release(a.reservationId); // already released: no-op, must not free b's slot
  assert.equal((await reserve(r1, at(3))).reason, 'max_per_window_reached');
  await release('garbage'); await release(undefined); await release(null);
  console.log('ok 4 release');
}

// 5. Released slot does not count toward the gap either
{
  const L = 'gap_rel';
  const r1 = req({ userId: L, minGapMinutes: 90 });
  const a = await reserve(r1, at(0));
  await release(a.reservationId);
  assert.equal((await reserve(r1, at(MIN))).allowed, true);
  console.log('ok 5 released slot ignored by gap');
}

// 6. Stale lock left by a crashed worker is recovered
{
  const L = 'stale_lead';
  const key = (await import('node:crypto')).createHash('sha256').update(L).digest('hex');
  const lock = path.join(STATE, 'leads', `${key}.lock`);
  mkdirSync(lock, { recursive: true });
  const old = new Date(Date.now() - 60_000);
  utimesSync(lock, old, old);
  const a = await reserve(req({ userId: L }), at(0));
  assert.equal(a.allowed, true);
  console.log('ok 6 stale lock recovered');
}

// 7. Validation: bad input throws, nothing is sent
{
  await assert.rejects(reserve(req({ maxPerWindow: 0 }), at(0)), TypeError);
  await assert.rejects(reserve(req({ windowHours: 3000 }), at(0)), RangeError);
  await assert.rejects(reserve(req({ minGapMinutes: -1 }), at(0)), RangeError);
  await assert.rejects(reserve(req(), 'nope'), TypeError);
  console.log('ok 7 validation');
}
console.log('ALL PASSED; state dir', STATE);
EOF
